def expand(items, w):
    out = []
    for it in items:
        if it == 'W':
            out.extend(w)
        elif it[0] == 'R':
            out.extend(SP(it[1]))
        else:
            out.append((it[1], it[2]))
    return tuple(out)


def expand_cfg(cfg, w):
    st, pb, A, g0, s, items, G = cfg
    return (st, pb, A, g0, s, expand(items, w), G)


def waypoints_rle(j, b):
    """The full asserted waypoint chain TOP11 -> ... -> TOP12
    (plus the r12' = 2 / 4 / 6 and band closing waypoints), in
    run-length form: pair lists are item lists ('P', a, b) /
    ('R', n) / 'W'.  Kept unexpanded -- at this phase's scale
    one expanded chain is ~80 GB of tuples."""
    j12 = j - 11874957
    tail = (('P', 1, 1), ('R', b - 1))
    pts = []
    pts.append(('C', TOP11F, 8675859, 11874954, 2,
                (('P', 2 * j - 2, 2),) + tail, 1))
    pts.append(('B', TOP11F, 8675858, 1, 11874954,
                (('P', 2, 2), ('P', 2 * j - 2, 2)) + tail, 1))
    pts.append(('C', F12, 11874954, 1, 2,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('B', F12, 11874954, 1, 4,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('C', F12, 11874954, 3, 2,
                (('P', 2 * j - 6, 2),) + tail, 1))
    pts.append(('C', F12, 0, 3, 2, (('R', 11874954), 'W'), 1))
    pts.extend(CASCADE58_WPS)
    # TOP12 state reached; closing waypoints by r12' = 2 * j12.
    if j12 == 1:
        pts.append(('B', (14897639,) + TOP12F, 29403094, 1, 3,
                    (('R', b - 1),), 1))
    if j12 == 2:
        pts.append(('C', TOP12F, 14897638, 29403092, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP12F, 14897637, 1, 29403092,
                    (('P', 2, 2), ('P', 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', (29403093, 14897638) + TOP12F, 3, 1, 3,
                    (('R', b - 1),), 1))
    if j12 == 3:
        pts.append(('C', TOP12F, 14897638, 29403092, 2,
                    (('P', 4, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP12F, 14897637, 1, 29403092,
                    (('P', 2, 2), ('P', 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F13, 29403092, 1, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', F13, 29403092, 1, 4,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', (29403093, 14897638) + TOP12F, 5, 1, 3,
                    (('R', b - 1),), 1))
    if j12 >= 4:
        pts.append(('C', TOP12F, 14897638, 29403092, 2,
                    (('P', 2 * j12 - 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', TOP12F, 14897637, 1, 29403092,
                    (('P', 2, 2), ('P', 2 * j12 - 2, 2),
                     ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('C', F13, 29403092, 1, 2,
                    (('P', 2 * j12 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F13, 29403092, 1, 4,
                    (('P', 2 * j12 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F13, 29403092, 3, 2,
                    (('P', 2 * j12 - 6, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F13, 29403092, 1, 2 * j12 - 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
    return pts


def check_chain(j, b, cap=60000000):
    """check_chain with lazy waypoint expansion (the Phase 56
    scale forbids materialising the whole chain).  Matching,
    skip recording and lemmastep replay verification are
    hsim55's, verbatim in behaviour."""
    rle = waypoints_rle(j, b)
    w = W(2 * j - 23749908, b)
    N = len(rle)
    cache = {}

    def target(k):
        if k not in cache:
            if len(cache) > 24:
                cache.clear()
            cache[k] = norm(expand_cfg(rle[k], w))
        return cache[k]

    pos = -1
    status = fin = None
    used = set()
    src = TOP11(j, b)
    anchor = norm(src)
    skips = []  # (anchor, [skipped waypoints], landing)
    for rec in swalk(src, max_steps=cap):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            status, fin, used = rec[1], rec[2], rec[3]
            break
        if pos + 1 < N:
            if _matches(rec, target(pos + 1)):
                pos += 1
                anchor = target(pos)
            else:
                for k in range(pos + 2, min(pos + 9, N)):
                    if _matches(rec, target(k)):
                        skips.append((anchor,
                                      [target(t)
                                       for t in range(pos + 1, k)],
                                      target(k)))
                        pos = k
                        anchor = target(pos)
                        break
    assert pos == N - 1, \
        'j=%d b=%d: waypoint %d missing: %s' \
        % (j, b, pos + 1, fmt(target(pos + 1)))
    for (anchor, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = anchor
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('verify replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'j=%d b=%d: skipped waypoint not verified: %s' \
            % (j, b, fmt(targets[ti]))
    return status, fin, pos, used


def front_check(j, b):
    """The front segment TOP11(j, b) -> DIP12 spine (waypoints
    0..5), with check_chain's skip recording + lemmastep
    replay verification and early exit at the spine."""
    rle = waypoints_rle(j, b)
    w = W(2 * j - 23749908, b)
    pts = [norm(expand_cfg(c, w)) for c in rle[:6]]
    pos = -1
    anchor = norm(TOP11(j, b))
    skips = []
    for rec in swalk(TOP11(j, b), max_steps=20000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if pos + 1 < len(pts):
            if _matches(rec, pts[pos + 1]):
                pos += 1
                anchor = pts[pos]
            else:
                for k in range(pos + 2, min(pos + 9, len(pts))):
                    if _matches(rec, pts[k]):
                        skips.append((anchor, pts[pos + 1:k],
                                      pts[k]))
                        pos = k
                        anchor = pts[pos]
                        break
        if pos == len(pts) - 1:
            break
    assert pos == len(pts) - 1, \
        'front j=%d b=%d: waypoint %d missing' % (j, b, pos + 1)
    for (a0, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = a0
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('front replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'front j=%d b=%d: skipped waypoint not verified' \
            % (j, b)


def TOP12(j12, b):
    return ('B', TOP12F, 14897638, 1, 29403093,
            ((2 * j12, 2), (1, 1)) + tuple(SP(b - 1)), 1)


def main():
    """Execution structure (Phase 58 scale): Part 1 (the
    canonical chain) and Part 1b (the junk-tail probe) are
    executed SPAN-SLICED via phase58-work/walkslice58.py
    (checkpointed slice queues phase58-work/jobs and
    jobs-junk; each slice replicates check_chain's matching
    and lemmastep skip-replay verification on its segment);
    Parts 1c, 2, 3, 4 below run directly in this process.
    Running this main() monolithically re-executes Part 1
    and 1b in-process (hours at this scale)."""
    fails = 0
    used = set()
    # Part 1: the canonical full waypoint chain (11874958, 2).
    try:
        status, fin, pos, u = check_chain(11874958, 2)
        used.update(u)
        print('PASS chain j=11874958 b=2: %d waypoints in order, '
              'walk %s' % (len(waypoints_rle(11874958, 2)), status),
              flush=True)
    except AssertionError as e:
        fails += 1
        print('FAIL', e, flush=True)
    # Part 1b: CASCADE58 is tail-general -- junk tail probe.
    w0 = ((7, 2), (1, 1), (3, 2), (1, 2))
    src = ('C', F12, 0, 3, 2, tuple(SP(11874954)) + w0, 1)
    top12 = norm(('B', TOP12F, 14897638, 1, 29403093, w0, 1))
    ok = False
    for rec in swalk(src, max_steps=60000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if norm(rec) == top12:
            ok = True
            break
    print(('PASS' if ok else 'FAIL'),
          'tail-generality: TOP12 shape reached with junk tail',
          flush=True)
    fails += 0 if ok else 1
    # Part 1c: front segments at the other chain points (the
    # cascade parse is (j, beta)-uniform: classifier chains
    # at beta = 2, 3 are identical; the cascade segment is
    # walk-verified at the canonical point and for the junk
    # tail above).
    for (j, b) in [(11874958, 3), (11874959, 2), (11874960, 2),
                   (20000000, 2), (41278052, 2)]:
        try:
            front_check(j, b)
            print('PASS front segment j=%d b=%d: TOP11 -> DIP12 '
                  'spine' % (j, b), flush=True)
        except AssertionError as e:
            fails += 1
            print('FAIL', e, flush=True)
    # Part 2: TOP12-closing finals (walks from the TOP12
    # state, whose stack is just W).
    F13p = (14897639,) + TOP12F
    F14p = (29403093, 14897638) + TOP12F
    finals = {
        (1, 2): (F13p, 29403095),
        (1, 3): (F13p, 29403096),
        (2, 2): (F14p, 4),
        (2, 3): (F14p, 5),
        (3, 2): (F14p, 6),
        (3, 3): (F14p, 7),
        (1000000, 3): (F14p, 2000001),
        (29403095, 2): (F14p, 58806190),
    }
    for (j12, b), (fr, A) in sorted(finals.items()):
        status = fin = None
        for rec in swalk(TOP12(j12, b), max_steps=60000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                status, fin, u = rec[1], rec[2], rec[3]
                used.update(u)
                break
        want = ('B', tuple(fr), A, 1, 2 * b + 1, (), 1)
        ok = status == 'DONE' and norm(fin) == want
        print(('PASS' if ok else 'FAIL'),
              'TOP12 final j12=%d b=%d: %s (want A=%d frame %s)'
              % (j12, b, fmt(fin), A, list(fr)), flush=True)
        fails += 0 if ok else 1
    # Part 3: the thirteenth fence from the TOP12 state --
    # r12' >= 58806192 takes DIPGRIND at 29403092 (j12 is
    # TOP12's parameter).
    for (j12, b) in [(29403096, 2), (29403097, 2), (30000000, 2)]:
        g13 = norm(('C', F13, 29403092, 3, 2,
                    ((2 * j12 - 6, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        dip13 = norm(('C', F13, 0, 3, 2,
                      tuple(SP(29403092))
                      + ((2 * j12 - 58806190, 2), (1, 1))
                      + tuple(SP(b - 1)), 1))
        seen_g13 = seen_dip13 = False
        for rec in swalk(TOP12(j12, b), max_steps=60000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                break
            n = norm(rec)
            if n == g13:
                seen_g13 = True
            elif seen_g13 and n == dip13:
                seen_dip13 = True
                break
        ok = seen_g13 and seen_dip13
        print(('PASS' if ok else 'FAIL'),
              'fence j12=%d: GRIND13 then thirteenth DIPGRIND '
              'landing occur (r12p=%d)' % (j12, 2 * j12),
              flush=True)
        fails += 0 if ok else 1
    # Part 4: primitive-step audit over the terminating
    # walks (the slice walks' records are produced by the
    # same mwalk/step_all; the classifier's step vocabulary
    # is exactly the PROVED_RULES lemma set).
    bad = used - PROVED_RULES
    print(('PASS' if not bad else 'FAIL'),
          'primitive rules used %s all in PROVED_RULES'
          % (sorted(used),), flush=True)
    fails += 0 if not bad else 1
    print()
    print('ALL PHASE 58 CHECKS PASS' if fails == 0
          else '%d FAILURES' % fails)
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
